<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { automationApi } from '@/api/automation'
const items=ref<any[]>([]),deliveries=ref<any[]>([]),tab=ref('all'),loading=ref(true),settingsOpen=ref(false),saving=ref(false)
const preferences=reactive<any>({timezone:'Asia/Shanghai',quiet_hours_enabled:false,quiet_start:'22:00',quiet_end:'08:00',digest_enabled:true,email_enabled:false,email_address:'',webhook_enabled:false,webhook_url:'',webhook_secret:''})
async function load(){loading.value=true;try{items.value=await automationApi.notifications(tab.value==='all'?undefined:tab.value);deliveries.value=await automationApi.deliveries()}finally{loading.value=false}}
async function mark(item:any,status:'read'|'archived'){await automationApi.markNotification(item.id,status);await load()}
async function readAll(){await automationApi.readAll();ElMessage.success('已全部标记为已读');await load()}
async function openSettings(){Object.assign(preferences,await automationApi.preferences(),{webhook_secret:''});settingsOpen.value=true}
async function saveSettings(){saving.value=true;try{await automationApi.updatePreferences(preferences);settingsOpen.value=false;ElMessage.success('通知偏好已保存')}finally{saving.value=false}}
function icon(type:string){return({report:'Document',subscription:'Bell',task:'Timer',alert:'Warning'} as any)[type]||'InfoFilled'}
onMounted(load)
</script>
<template><main class="notifications-page"><header><div><small>NOTIFICATION INBOX</small><h1>通知中心</h1><p>订阅变化、任务结果、报告生成和投递异常。</p></div><div><button title="通知设置" @click="openSettings"><el-icon><Setting /></el-icon></button><button @click="readAll"><el-icon><Check /></el-icon>全部已读</button></div></header><nav class="tabs"><button :class="{active:tab==='all'}" @click="tab='all';load()">全部</button><button :class="{active:tab==='unread'}" @click="tab='unread';load()">未读</button><button :class="{active:tab==='archived'}" @click="tab='archived';load()">已归档</button></nav><section class="notification-layout"><div v-loading="loading" class="inbox"><article v-for="item in items" :key="item.id" :class="[item.severity,{unread:item.status==='unread'}]"><div class="icon"><el-icon><component :is="icon(item.type)"/></el-icon></div><div><header><span>{{item.type}}</span><time>{{new Date(item.created_at).toLocaleString()}}</time></header><h2>{{item.title}}</h2><p>{{item.body}}</p><footer><button v-if="item.payload.report_id" @click="$router.push(`/reports/${item.payload.report_id}`)">打开报告</button><button v-if="item.status==='unread'" @click="mark(item,'read')">标记已读</button><button @click="mark(item,'archived')">归档</button></footer></div></article><div v-if="!loading&&!items.length" class="empty"><el-icon><Bell /></el-icon><h2>暂无通知</h2><p>任务和订阅产生真实结果后会显示在这里。</p></div></div><aside><header><small>DELIVERY LOG</small><h2>外部投递</h2></header><article v-for="delivery in deliveries" :key="delivery.id"><div><b>{{delivery.channel}}</b><span :class="delivery.status">{{delivery.status}}</span></div><p>{{delivery.title}}</p><small>尝试 {{delivery.attempt}} 次<span v-if="delivery.response_code"> · HTTP {{delivery.response_code}}</span></small><em v-if="delivery.error_message">{{delivery.error_message}}</em></article><div v-if="!deliveries.length" class="mini-empty">尚无邮件或 Webhook 投递记录</div></aside></section><div v-if="settingsOpen" class="overlay" @click.self="settingsOpen=false"><form @submit.prevent="saveSettings"><header><h2>通知偏好</h2><button type="button" @click="settingsOpen=false"><el-icon><Close /></el-icon></button></header><label>时区<select v-model="preferences.timezone"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option></select></label><fieldset><legend>免打扰</legend><label class="toggle"><input v-model="preferences.quiet_hours_enabled" type="checkbox"/>启用免打扰</label><div v-if="preferences.quiet_hours_enabled" class="grid"><label>开始<input v-model="preferences.quiet_start" type="time"/></label><label>结束<input v-model="preferences.quiet_end" type="time"/></label></div></fieldset><fieldset><legend>通知聚合</legend><label class="toggle"><input v-model="preferences.digest_enabled" type="checkbox"/>合并同类通知</label></fieldset><fieldset><legend>邮件</legend><label class="toggle"><input v-model="preferences.email_enabled" type="checkbox"/>启用邮件</label><label v-if="preferences.email_enabled">收件地址<input v-model="preferences.email_address" type="email" required/></label></fieldset><fieldset><legend>Webhook</legend><label class="toggle"><input v-model="preferences.webhook_enabled" type="checkbox"/>启用 Webhook</label><template v-if="preferences.webhook_enabled"><label>公网 HTTPS 地址<input v-model="preferences.webhook_url" type="url" required placeholder="https://example.com/webhook"/></label><label>签名密钥<input v-model="preferences.webhook_secret" type="password" :required="!preferences.webhook_secret_configured"/></label><p>Webhook 属于高风险外部动作，关联任务需要单独确认。</p></template></fieldset><footer><button type="button" @click="settingsOpen=false">取消</button><button class="primary" :disabled="saving">保存设置</button></footer></form></div></main></template>
<style scoped>.notifications-page{min-height:100vh;padding:36px clamp(18px,4vw,60px);color:#17231f;background:#f3f6f5}.notifications-page>header{display:flex;align-items:end;justify-content:space-between;padding-bottom:24px;border-bottom:1px solid #cad7d2}.notifications-page>header small{color:#167f76;font-weight:800}.notifications-page h1{margin:7px 0;font:650 40px Georgia,"Songti SC",serif}.notifications-page>header p{margin:0;color:#6d7f78}.notifications-page>header>div:last-child{display:flex;gap:7px}.notifications-page>header button{height:38px;padding:0 12px;border:1px solid #cbd7d2;border-radius:4px;background:#fff}.tabs{padding:18px 0 10px;display:flex;gap:4px}.tabs button{padding:8px 13px;border:0;border-radius:4px;color:#667871;background:transparent}.tabs button.active{color:#fff;background:#183129}.notification-layout{display:grid;grid-template-columns:minmax(500px,1fr) 300px;gap:13px}.inbox,aside{min-height:480px;border:1px solid #cbd7d2;border-radius:7px;background:#fff}.inbox article{padding:17px;display:grid;grid-template-columns:42px 1fr;gap:12px;border-top:1px solid #e0e7e4}.inbox article:first-child{border:0}.inbox article.unread{box-shadow:inset 3px 0 #167f76;background:#f9fcfb}.inbox article.error{box-shadow:inset 3px 0 #d34b48}.icon{width:36px;height:36px;border-radius:5px;display:grid;place-items:center;color:#167f76;background:#e3f0ec}.inbox article header{display:flex;justify-content:space-between;color:#788983;font-size:9px;text-transform:uppercase}.inbox h2{margin:6px 0;font-size:16px}.inbox p{margin:0;white-space:pre-line;color:#60736c;font-size:11px;line-height:1.6}.inbox footer{margin-top:10px}.inbox footer button{margin-right:6px;padding:5px 8px;border:1px solid #ccd7d3;color:#16776e;background:#fff;font-size:9px}.empty{min-height:460px;display:grid;place-items:center;align-content:center;text-align:center;color:#75867f}.empty .el-icon{font-size:44px}aside{padding:16px}aside>header small{color:#167f76;font-size:9px}aside>header h2{margin:5px 0 13px}aside article{padding:12px 0;border-top:1px solid #dce4e1}aside article>div{display:flex;justify-content:space-between}aside article span{padding:2px 5px;border-radius:3px;background:#e8eeeb;font-size:8px}aside article span.delivered{color:#087759;background:#dff3ec}aside article span.dead_letter{color:#a73434;background:#fbe4e3}aside article p{margin:6px 0;font-size:11px}aside article small{color:#7b8a85}aside article em{display:block;margin-top:5px;color:#a43838;font-size:9px}.mini-empty{padding:50px 10px;color:#7c8b86;text-align:center;font-size:11px}.overlay{position:fixed;inset:0;z-index:600;display:grid;place-items:center;padding:15px;background:rgba(10,27,21,.44)}.overlay form{width:min(540px,100%);max-height:90vh;padding:22px;overflow:auto;border-radius:7px;background:#fff}.overlay form>header,.overlay footer{display:flex;align-items:center;justify-content:space-between}.overlay h2{margin:0}.overlay header button{border:0;background:transparent}.overlay label{margin-top:13px;display:grid;gap:6px;font-size:11px}.overlay input,.overlay select{height:39px;padding:0 8px;border:1px solid #cbd7d2}fieldset{margin-top:15px;border:1px solid #d2dcd8}fieldset .toggle{display:flex;align-items:center;gap:6px}fieldset .toggle input{height:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}fieldset p{color:#9b5a0f;font-size:10px}.overlay footer{margin-top:20px;justify-content:flex-end;gap:7px}.overlay footer button{height:38px;padding:0 13px;border:1px solid #cbd7d2;background:#fff}.overlay footer .primary{border:0;color:#fff;background:#183129}@media(max-width:900px){.notification-layout{grid-template-columns:1fr}aside{min-height:260px}}@media(max-width:600px){.notifications-page h1{font-size:31px}.notifications-page>header p{display:none}.notification-layout{grid-template-columns:1fr}.grid{grid-template-columns:1fr}}</style>
